-- Drop tables
ALTER TABLE "author" DROP CONSTRAINT IF EXISTS "idx_author_email";
CREATE UNIQUE INDEX "idx_author_email" ON "author" ("email");
DROP SCHEMA public CASCADE;
CREATE SCHEMA public;

DROP INDEX IF EXISTS "idx_author_email";
DROP INDEX IF EXISTS "idx_author_genre";
DROP INDEX IF EXISTS "idx_author_country";

-- Table `author`
CREATE TABLE "author" (
  "id"               BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "name"             VARCHAR(150) NOT NULL,
  "email"            VARCHAR(255) NOT NULL,
  "primary_genre"    VARCHAR(80)  DEFAULT NULL,
  "country_code"     VARCHAR(2)   DEFAULT NULL,
  "birth_date"       DATE         DEFAULT NULL,
  "biography"        TEXT         DEFAULT NULL,
  "social_metadata"  JSONB        DEFAULT NULL,
  "sell_rank"        INTEGER      DEFAULT NULL,
  "total_books_sold" BIGINT       DEFAULT NULL,
  "last_active_at"   TIMESTAMPTZ  DEFAULT NULL,
  CONSTRAINT "author_pk" PRIMARY KEY ("id"),
  CONSTRAINT "idx_author_email" UNIQUE ("email")
) WITH (fillfactor = 80);

CREATE INDEX "idx_author_genre" ON "author" ("primary_genre");
CREATE INDEX "idx_author_country" ON "author" ("country_code");

-- fillfactor = 80
-- Setting fillfactor = 80 tells PostgreSQL to leave 20% of every 8KB heap page 
-- empty during INSERTs. That reserved headroom allows future UPDATEs on sell_rank or total_books_sold 
-- to write the new row version onto the same page, satisfying the storage requirement for a HOT update.